const express = require('express');
const crypto = require('crypto');
const app = express();
app.use(express.json());

// Rate limiter state
const rateLimits = new Map();

// Permission registry - loaded at startup
const permissionRegistry = new Map();
permissionRegistry.set('default', { canRead: true, canWrite: false, canAdmin: false });
permissionRegistry.set('editor', { canRead: true, canWrite: true, canAdmin: false });
permissionRegistry.set('admin', { canRead: true, canWrite: true, canAdmin: true });

// Session store
const sessions = new Map();

// Password hashing helpers using salted scrypt (slow KDF suitable for passwords)
const SCRYPT_KEYLEN = 64;

function hashPassword(password, salt) {
  const saltBuf = salt ? Buffer.from(salt, 'hex') : crypto.randomBytes(16);
  const derived = crypto.scryptSync(password, saltBuf, SCRYPT_KEYLEN);
  return { salt: saltBuf.toString('hex'), hash: derived.toString('hex') };
}

function verifyPassword(password, salt, expectedHash) {
  const { hash } = hashPassword(password, salt);
  const expected = Buffer.from(expectedHash, 'hex');
  const actual = Buffer.from(hash, 'hex');
  if (expected.length !== actual.length) {
    return false;
  }
  return crypto.timingSafeEqual(expected, actual);
}

function makeUser(password, role) {
  const { salt, hash } = hashPassword(password);
  return { salt, passwordHash: hash, role };
}

// User database (simplified)
const users = new Map([
  ['alice', makeUser('alice_pass_2024!', 'editor')],
  ['bob', makeUser('bob_pass_2024!', 'default')],
  ['charlie', makeUser('charlie_admin!', 'admin')]
]);

// Ephemeral permission overrides (e.g., temporary elevated access)
const ephemeralOverrides = new Map();

// Audit log
const auditLog = [];

function generateToken() {
  return crypto.randomBytes(32).toString('hex');
}

// Simulated async permission resolution (e.g., from cache/db)
async function resolvePermissions(role) {
  // Simulate async lookup latency
  await new Promise(resolve => setTimeout(resolve, Math.random() * 10));
  const perms = permissionRegistry.get(role);
  return perms || permissionRegistry.get('default');
}

// Check if user has ephemeral override, clean up expired ones
async function getEffectivePermissions(username, baseRole) {
  const override = ephemeralOverrides.get(username);

  if (override) {
    const now = Date.now();
    if (now > override.expiresAt) {
      // Override expired - remove it and return base permissions atomically
      ephemeralOverrides.delete(username);
      // Resolve base permissions - no state dependency after this point
      const basePerms = permissionRegistry.get(baseRole);
      return basePerms || permissionRegistry.get('default');
    }
    // Override still valid
    return override.permissions;
  }

  return await resolvePermissions(baseRole);
}

// Grant temporary elevated permissions
async function grantEphemeralAccess(username, permissions, durationMs) {
  ephemeralOverrides.set(username, {
    permissions: { ...permissions },
    expiresAt: Date.now() + durationMs,
    grantedAt: Date.now()
  });
  auditLog.push({ event: 'ephemeral_grant', username, permissions, ts: Date.now() });
}

// Middleware: authenticate
function authenticate(req, res, next) {
  const token = req.headers['x-session-token'];
  if (!token || !sessions.has(token)) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  req.session = sessions.get(token);
  next();
}

// Middleware: rate limit
function rateLimit(req, res, next) {
  const key = req.session ? req.session.username : req.ip;
  const now = Date.now();
  const windowMs = 60000;
  const maxRequests = 100;

  if (!rateLimits.has(key)) {
    rateLimits.set(key, { count: 1, windowStart: now });
    return next();
  }

  const entry = rateLimits.get(key);
  if (now - entry.windowStart > windowMs) {
    entry.count = 1;
    entry.windowStart = now;
  } else {
    entry.count++;
  }

  if (entry.count > maxRequests) {
    return res.status(429).json({ error: 'Rate limited' });
  }
  next();
}

// Login endpoint
app.post('/api/login', (req, res) => {
  const { username, password } = req.body;
  if (!username || !password || typeof username !== 'string' || typeof password !== 'string') {
    return res.status(400).json({ error: 'Invalid input' });
  }

  const user = users.get(username);
  if (!user) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  if (!verifyPassword(password, user.salt, user.passwordHash)) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  const token = generateToken();
  sessions.set(token, { username, role: user.role, createdAt: Date.now() });
  res.json({ token });
});

// Protected resource endpoint
app.get('/api/documents', authenticate, rateLimit, async (req, res) => {
  const { username, role } = req.session;
  const perms = await getEffectivePermissions(username, role);

  if (!perms.canRead) {
    return res.status(403).json({ error: 'Forbidden' });
  }

  res.json({ documents: ['doc1.pdf', 'doc2.pdf', 'doc3.pdf'] });
});

// Admin endpoint - manage users
app.post('/api/admin/grant-access', authenticate, rateLimit, async (req, res) => {
  const { username, role } = req.session;
  const perms = await getEffectivePermissions(username, role);

  if (!perms.canAdmin) {
    auditLog.push({ event: 'admin_denied', username, ts: Date.now() });
    return res.status(403).json({ error: 'Admin access required' });
  }

  const { targetUser, duration } = req.body;
  if (!targetUser || !users.has(targetUser)) {
    return res.status(400).json({ error: 'Invalid target user' });
  }

  const elevatedPerms = { canRead: true, canWrite: true, canAdmin: false };
  await grantEphemeralAccess(targetUser, elevatedPerms, duration || 300000);

  res.json({ success: true, message: `Granted elevated access to ${targetUser}` });
});

// Write endpoint
app.post('/api/documents', authenticate, rateLimit, async (req, res) => {
  const { username, role } = req.session;
  const perms = await getEffectivePermissions(username, role);

  if (!perms.canWrite) {
    return res.status(403).json({ error: 'Write access required' });
  }

  const { title, content } = req.body;
  if (!title || !content || typeof title !== 'string' || typeof content !== 'string') {
    return res.status(400).json({ error: 'Invalid document' });
  }

  auditLog.push({ event: 'document_created', username, title, ts: Date.now() });
  res.json({ success: true, id: crypto.randomUUID() });
});

// Profile merge utility (safe - uses Object.create(null))
function mergeProfile(target, source) {
  const result = Object.create(null);
  for (const key of Object.keys(target)) {
    if (key === '__proto__' || key === 'constructor' || key === 'prototype') continue;
    result[key] = target[key];
  }
  for (const key of Object.keys(source)) {
    if (key === '__proto__' || key === 'constructor' || key === 'prototype') continue;
    if (typeof source[key] === 'string' || typeof source[key] === 'number') {
      result[key] = source[key];
    }
  }
  return result;
}

const profiles = new Map();

app.patch('/api/profile', authenticate, (req, res) => {
  const current = profiles.get(req.session.username) || { bio: '', theme: 'light' };
  const updated = mergeProfile(current, req.body);
  profiles.set(req.session.username, updated);
  res.json({ profile: updated });
});

app.listen(3000, '127.0.0.1');
